class Limiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.records = defaultdict(lambda: {})

    def hit(self, key, now):
        if key not in self.records:
            self.records[key] = {}
        prev = now - self.window
        if prev not in self.records[key]:
            self.records[key][prev] = 0
        count = self.records[key][prev] + 1
